//! Shared model adapter for anchored workspace workers. No model lives in a worker.
use serde_json::{json,Value};
use crate::{workspace_worker::Workers,semantic::SemanticService};
use sha2::{Digest,Sha256};
pub(crate) type VectorCache=std::collections::HashMap<String,Box<[f32;512]>>;
pub(crate) fn input_key(field:&str,title:&str,text:&str)->String {let input=if field=="title"{title.to_owned()}else{format!("{title}\n{text}")};format!("{:x}",Sha256::digest(input.as_bytes()))}
pub(crate) fn make_cache(index:&atlas_faiss_probe::Index,records:&[Value])->VectorCache{make_cache_partial(index,records,records.len())}
pub(crate) fn make_cache_partial(index:&atlas_faiss_probe::Index,records:&[Value],count:usize)->VectorCache{let mut out=VectorCache::new();if index.count()!=count as i64{return out}for (i,r) in records.iter().take(16000).enumerate(){let field=r["field"].as_str().unwrap_or("");let key=if field=="image"{r["input_hash"].as_str().map(str::to_owned)}else{match (r["title"].as_str(),r["text"].as_str()){(Some(title),Some(text))=>Some(input_key(field,title,text)),_=>None}};if let Some(key)=key{if let Ok(v)=index.reconstruct(i as i64){out.insert(key,Box::new(v));}}}out}
type R<T>=Result<T,Box<dyn std::error::Error>>;
fn call(workers:&Workers,id:&str,session:&str,value:Value)->R<Value>{let result=workers.request_session(id,session,&value)?;if let Some(e)=result["error"].as_str(){return Err(e.to_owned().into())}result.get("ok").cloned().ok_or_else(||"invalid worker response".into())}
pub fn rebuild(workers:&Workers,id:&str,service:&SemanticService)->R<()> {let session=workers.session(id)?;rebuild_session(workers,id,&session,service)}
pub fn rebuild_session(workers:&Workers,id:&str,session:&str,service:&SemanticService)->R<()> {
 rebuild_control(workers,id,session,service,|_,_|true,||{call(workers,id,session,json!({"action":"index-commit"}))?;Ok(())})
}
pub fn rebuild_control(workers:&Workers,id:&str,session:&str,service:&SemanticService,mut progress:impl FnMut(&str,usize)->bool,commit:impl FnOnce()->R<()>)->R<()> {
 let mut completed=0usize;let model=service.worker_model_identity()?;let mut after:Option<String>=None;let mut revision:Option<String>=None;
 loop {let page=call(workers,id,session,json!({"action":"index-snapshot","after":after,"images":service.worker_images_enabled()}))?;let current=page["revision"].as_str().ok_or("missing revision")?;
  if let Some(expected)=&revision {if expected!=current{return Err("workspace changed during indexing".into())}}else{revision=Some(current.to_owned());call(workers,id,session,json!({"action":"index-begin","revision":current,"model":model}))?;}
  for doc in page["documents"].as_array().ok_or("missing documents")? {let docid=doc["id"].as_str().ok_or("missing id")?;let title=doc["title"].as_str().ok_or("missing title")?;if !progress(title,completed){let _=call(workers,id,session,json!({"action":"index-abort"}));return Err("cancelled".into())}let mut offset=0u64;let mut body_empty=false;
   loop {let chunks=call(workers,id,session,json!({"action":"index-chunks","revision":current,"id":docid,"offset":offset}))?;if chunks["revision"].as_str()!=Some(current){return Err("workspace changed during indexing".into())}if offset==0{body_empty=chunks["body_empty"].as_bool().ok_or("missing body status")?;}for chunk in chunks["chunks"].as_array().ok_or("missing chunks")? {if !progress(title,completed){let _=call(workers,id,session,json!({"action":"index-abort"}));return Err("cancelled".into())}let content=chunk["text"].as_str().ok_or("missing chunk")?;let input=format!("{title}\n{content}");let key=input_key(chunk["field"].as_str().unwrap_or("body"),title,content);let cached=call(workers,id,session,json!({"action":"index-reuse","key":key}))?;let vector=if cached["vector"].is_array(){cached["vector"].clone()}else{json!(service.worker_encode(&input,false)?)};let record=json!({"input_hash":key,"id":docid,"title":title,"field":chunk["field"],"text":content,"start":chunk["start"],"end":chunk["end"],"start_utf16":chunk["start_utf16"],"end_utf16":chunk["end_utf16"],"vector":vector});call(workers,id,session,json!({"action":"index-add","records":[record]}))?;completed+=1;}match chunks["next"].as_u64(){Some(next)=>offset=next,None=>break}}
   if service.worker_images_enabled() {let lower=title.to_ascii_lowercase();let mime=if lower.ends_with(".png"){Some("image/png")}else if lower.ends_with(".jpg")||lower.ends_with(".jpeg"){Some("image/jpeg")}else if lower.ends_with(".webp"){Some("image/webp")}else if lower.ends_with(".gif"){Some("image/gif")}else{None};if let Some(mime)=mime {let image=(||->R<Vec<u8>>{let opened=call(workers,id,session,json!({"action":"download-begin","id":docid}))?;let stream=opened["stream"].as_str().ok_or("missing stream")?;if opened["size"].as_u64().unwrap_or(u64::MAX)>32*1024*1024 {let _=call(workers,id,session,json!({"action":"download-cancel","stream":stream}));return Err("image too large".into())}let mut bytes=Vec::new();loop {let block=call(workers,id,session,json!({"action":"download-next","stream":stream}))?;for byte in block["bytes"].as_array().ok_or("invalid bytes")?{bytes.push(u8::try_from(byte.as_u64().ok_or("invalid byte")?)?)}if block["done"]==true {break}}Ok(bytes)})();match image.and_then(|bytes|{let key=format!("image:{mime}:{:x}",Sha256::digest(&bytes));let cached=call(workers,id,session,json!({"action":"index-reuse","key":key}))?;let vector=if cached["vector"].is_array(){cached["vector"].clone()}else{json!(service.worker_encode_image(&bytes,mime)?)};Ok((key,vector))}){Ok((key,vector))=>{call(workers,id,session,json!({"action":"index-add","records":[{"input_hash":key,"id":docid,"title":title,"field":"image","text":"","start":null,"end":null,"vector":vector}]}))?;},Err(e)=>eprintln!("Atlas: image indexing skipped: {e}")}}}
   if body_empty&&!title.trim().is_empty(){let key=input_key("title",title,title);let cached=call(workers,id,session,json!({"action":"index-reuse","key":key}))?;let vector=if cached["vector"].is_array(){cached["vector"].clone()}else{json!(service.worker_encode(title,false)?)};call(workers,id,session,json!({"action":"index-add","records":[{"input_hash":key,"id":docid,"title":title,"field":"title","text":title,"start":null,"end":null,"vector":vector}]}))?;}
  }
  after=page["next"].as_str().map(str::to_owned);if after.is_none(){break}
 }
 commit()?;Ok(())
}
pub fn search(workers:&Workers,id:&str,service:&SemanticService,query:&str,ids:Option<&[String]>)->R<Value>{let session=workers.session(id)?;search_session(workers,id,&session,service,query,ids)}
pub fn search_session(workers:&Workers,id:&str,session:&str,service:&SemanticService,query:&str,ids:Option<&[String]>)->R<Value>{let model=service.worker_model_identity()?;let vector=service.worker_encode(query,true)?;let response=call(workers,id,session,json!({"action":"index-search","model":model,"vector":vector,"ids":ids}))?;let mut results=Vec::new();for item in response["results"].as_array().ok_or("invalid worker results")?{let chunks=if item["field"]=="title"{vec![]}else{vec![json!({"text":item["text"],"field":item["field"],"start":item["start"],"end":item["end"],"start_utf16":item["start_utf16"],"end_utf16":item["end_utf16"],"score":item["score"]})]};results.push(json!({"id":item["id"],"title":item["title"],"score":item["score"],"chunks":chunks}));}Ok(json!({"revision":response["revision"],"results":results}))}
#[cfg(feature="test-hook")]
pub fn probe()->R<()> {use std::{fs,io::Read};let mut input=String::new();std::io::stdin().read_to_string(&mut input)?;let v:Value=serde_json::from_str(&input)?;let dir=fs::File::open(v["workspace"].as_str().ok_or("workspace")?)?;let service=SemanticService::start(v["exe"].as_str().ok_or("exe")?,v["model"].as_str().ok_or("model")?)?;let workers=Workers::default();let id="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";workers.attach(id,&dir,std::path::Path::new(v["workspace"].as_str().ok_or("workspace")?))?;rebuild(&workers,id,&service)?;let result=search(&workers,id,&service,v["query"].as_str().ok_or("query")?,None)?;println!("{}",result);Ok(())}
#[cfg(test)] mod reuse_tests {
 use super::*;
 #[test] fn large_cache_is_bounded_and_retains_first_vectors(){
  let mut index=atlas_faiss_probe::Index::new().unwrap();let vector=[0.5f32;512];let mut records=Vec::new();
  for i in 0..16001 {index.add(&[vector]).unwrap();records.push(json!({"field":"body","title":"Title","text":format!("fragment {i}")}));}
  let cache=make_cache(&index,&records);assert_eq!(cache.len(),16000);assert_eq!(cache[&input_key("body","Title","fragment 0")][0],0.5);assert!(!cache.contains_key(&input_key("body","Title","fragment 16000")));assert!(!cache.contains_key(&input_key("body","Changed","fragment 0")));
 }
}
